create or replace function public.get_manual_qr_payment_settings() returns jsonb language plpgsql stable security definer set search_path=public as $$ begin
 if not public.has_pos_permission('payment.view') then raise exception 'INSUFFICIENT_PERMISSION'; end if;
 return jsonb_build_object('enabled',coalesce((select (value#>>'{}')::boolean from public.pos_settings where key='payment.qr.enabled'),false),'scheme','DUITNOW','mode','STATIC','confirmationMode','MANUAL','imageUrl',coalesce((select value#>>'{}' from public.pos_settings where key='payment.qr.image_url'),''),'displayName',coalesce((select value#>>'{}' from public.pos_settings where key='payment.qr.display_name'),'Restaurant DuitNow QR'),'merchantName',coalesce((select value#>>'{}' from public.pos_settings where key='payment.qr.merchant_name'),'Restaurant'),'settlementBank',coalesce((select value#>>'{}' from public.pos_settings where key='payment.qr.settlement_bank'),''),'referenceRequired',coalesce((select (value#>>'{}')::boolean from public.pos_settings where key='payment.qr.reference_required'),false)); end; $$;
